INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Multicast-Ping nur für FF02::1 möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Gruppen wie FF02::2 möglich"}, {"text": "Ja", "correct": false, "because": "Mehrere Adressen nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse pinge ich, um alle Knoten im Segment zu erreichen?', 3, '[{"text": "FF02::1%Interface", "correct": true, "because": "Link-lokal alle Knoten"}, {"text": "FE80::1", "correct": false, "because": "Unicast-Adresse"}, {"text": "FF02::2", "correct": false, "because": "Nur Router"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind bei einem Multicast-Ping wichtig?', 5, '[{"text": "Gruppenadresse", "correct": true, "because": "z. B. FF02::1"}, {"text": "Interface-Angabe", "correct": true, "because": "Link-lokal erfordert %eth0"}, {"text": "Portnummer", "correct": false, "because": "Transportebene"}, {"text": "DNS-Name", "correct": false, "because": "IP-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FF02::1%Interface pingt alle Knoten. b) Es nutzt Unicast.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Multicast, nicht Unicast"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Multicast-Ping?', 4, '[{"text": "Interface", "correct": false, "because": "Nötig für Link-Local"}, {"text": "FF02::1", "correct": false, "because": "Zielgruppe definiert"}, {"text": "Datenpayload", "correct": true, "because": "Nur Diagnose, kein Inhalt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Multicast-Ping eine Scope-ID braucht?', 2, '[{"text": "Ja", "correct": true, "because": "%Interface definiert Scope"}, {"text": "Nein", "correct": false, "because": "Link-lokal erfordert es"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Antwort erwartest du bei FF02::1%eth0?', 3, '[{"text": "Echo Reply von mehreren", "correct": true, "because": "Alle Knoten antworten"}, {"text": "Destination Unreachable", "correct": false, "because": "Nur bei Fehler"}, {"text": "Single Reply", "correct": false, "because": "Nicht Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat ein Multicast-Ping?', 5, '[{"text": "Gruppenabfrage", "correct": true, "because": "Testet viele Geräte"}, {"text": "Netzwerkerkennung", "correct": true, "because": "Alle Knoten antworten"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht enthalten"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) FF02::1%Interface testet alle Knoten. b) Es überschreitet Router. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Link-lokal bleibt lokal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Multicast-Ping?', 4, '[{"text": "Gruppenadresse", "correct": false, "because": "Definiert Ziel"}, {"text": "Interface-ID", "correct": false, "because": "Für Link-Local nötig"}, {"text": "Webserver", "correct": true, "because": "Nicht Diagnose-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist FF02::1%Interface global gültig?', 2, '[{"text": "Nein", "correct": true, "because": "Link-lokal beschränkt"}, {"text": "Ja", "correct": false, "because": "Nur lokales Segment"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Interface-Angabe?', 4, '[{"text": "Definiert Scope", "correct": true, "because": "Link-Local braucht %eth0"}, {"text": "Erhöht Latenz", "correct": false, "because": "Netzwerkabhängig"}, {"text": "Weist IPs zu", "correct": false, "because": "SLAAC-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multicast-Ping nur für Router ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "FF02::1 für alle Knoten"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit FF02::2"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Multicast-Ping?', 3, '[{"text": "Korrekte Interface-ID", "correct": true, "because": "Link-Local erfordert es"}, {"text": "Hohe Paketgröße", "correct": false, "because": "Sekundär"}, {"text": "DNS-Eintrag", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FF02::1%Interface ist Multicast. b) Es nutzt TCP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ICMPv6, nicht TCP"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse liefert ein Multicast-Ping?', 5, '[{"text": "Mehrere Echo Replies", "correct": true, "because": "Von allen Knoten"}, {"text": "Latenzmessung", "correct": true, "because": "Zeigt Verzögerung"}, {"text": "IP-Zuweisung", "correct": false, "because": "SLAAC-Aufgabe"}, {"text": "Datenflusssteuerung", "correct": false, "because": "TCP-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Multicast-Ping unwichtig?', 3, '[{"text": "Gruppenadresse", "correct": false, "because": "Definiert Ziel"}, {"text": "Interface", "correct": false, "because": "Scope-spezifisch"}, {"text": "HTTP-Status", "correct": true, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erwartet ein Multicast-Ping eine einzelne Antwort?', 3, '[{"text": "Nein", "correct": true, "because": "Mehrere Geräte antworten"}, {"text": "Ja", "correct": false, "because": "Nicht wie Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Multicast-Ping Router überschreitet?', 2, '[{"text": "Nein", "correct": true, "because": "Link-lokal bleibt lokal"}, {"text": "Ja", "correct": false, "because": "Scope-beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für alle Router im Segment?', 4, '[{"text": "FF02::2%Interface", "correct": true, "because": "Router-Gruppe"}, {"text": "FF02::1%Interface", "correct": false, "because": "Alle Knoten"}, {"text": "FE80::2", "correct": false, "because": "Unicast"}]');
